using System;using System.Diagnostics;using System.Runtime.InteropServices;using System.Text;using TGLL;
class DataUpdatePopupTests {
 [UnmanagedFunctionPointer(CallingConvention.Cdecl)]delegate int Tick();
 [UnmanagedFunctionPointer(CallingConvention.Cdecl)]delegate bool Contains(IntPtr self,IntPtr item,IntPtr info);
 [UnmanagedFunctionPointer(CallingConvention.Cdecl)]delegate void Confirm(IntPtr self,int id,IntPtr payload,IntPtr button,IntPtr info);
 static void Check(bool b,string s){if(!b)throw new Exception(s);}static void I(Remote r,long a,int v){r.Write(a,BitConverter.GetBytes(v));}static void P(Remote r,long a,long v){r.Write(a,BitConverter.GetBytes(v));}
 static long S(Remote r,string s){long a=r.Allocate(24+s.Length*2);I(r,a+16,s.Length);r.Write(a+20,Encoding.Unicode.GetBytes(s));return a;}
 static int Main(){try{using(var r=new Remote(Process.GetCurrentProcess())){
 long d=r.Allocate(4096),login=r.Allocate(4096),cs=r.Allocate(8),ds=r.Allocate(8),cc=r.Allocate(512),dc=r.Allocate(1600),stat=r.Allocate(8),canvas=r.Allocate(512),screen=r.Allocate(512),popup=r.Allocate(512),button=r.Allocate(256),lines=r.Allocate(64),list=r.Allocate(32),vc=r.Allocate(1024),payload=r.Allocate(16);
 P(r,cs,cc);P(r,ds,dc);P(r,cc+0xb8,stat);P(r,stat,canvas);P(r,canvas+0x1b8,screen);P(r,popup,dc);P(r,popup+0xa8,screen);P(r,popup+0xc0,lines);P(r,popup+0xc8,button);I(r,lines+24,2);P(r,lines+32,S(r,"Cập nhật dữ liệu 0.1MB. Vui lòng kết nối"));P(r,lines+40,S(r,"Internet trước khi bắt đầu tải."));P(r,button+0x48,popup);P(r,button+0x78,S(r,"Xác nhận"));I(r,button+0x80,2111);P(r,button+0x98,payload);P(r,screen+0x88,list);P(r,list,vc);
 bool attached=true;int calls=0;Tick tick=null;Contains contains=delegate(IntPtr self,IntPtr item,IntPtr info){return attached&&item.ToInt64()==popup;};Confirm confirm=delegate(IntPtr self,int id,IntPtr data,IntPtr control,IntPtr info){Check(self.ToInt64()==popup&&id==2111&&data.ToInt64()==payload&&control.ToInt64()==button,"exact update action and payload");calls++;Check(tick()==1,"reentry holds without repeated confirm");};P(r,vc+0x208,Marshal.GetFunctionPointerForDelegate(contains).ToInt64());P(r,dc+0x488,Marshal.GetFunctionPointerForDelegate(confirm).ToInt64());
 long exe=r.Allocate(4096);r.Write(exe,NativeCode.PreLoginDataUpdate(d,login,cs,ds,0));r.Protect(exe,4096,0x20);tick=(Tick)Marshal.GetDelegateForFunctionPointer(new IntPtr(exe),typeof(Tick));I(r,login,1);
 Check(tick()==0&&calls==0,"no popup continues immediately");P(r,screen+0x90,popup);Check(tick()==1&&calls==1,"confirm update modal");Check(tick()==1&&calls==1,"pending same modal once only");attached=false;Check(tick()==0,"dismissed modal proceeds without delay");attached=true;P(r,lines+32,S(r,"Thông báo khác"));Check(tick()==0&&calls==1,"unrelated modal untouched");P(r,lines+32,S(r,"Cập nhật dữ liệu 12.75MB. Vui lòng kết nối"));I(r,button+0x80,2112);Check(tick()==0&&calls==1,"other action untouched");I(r,button+0x80,2111);I(r,login,12);Check(tick()==0&&calls==1,"gameplay is not polled");I(r,login,1);Check(tick()==1&&calls==2,"new update and variable size supported");
 GC.KeepAlive(contains);GC.KeepAlive(confirm);Console.WriteLine("PASS: update popup action2111, exact class/text/owner/button, variable size, once-only/reentry; absent or dismissed continues immediately; unrelated popup and gameplay untouched.");
 }return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
